// ======================================================================
// Policy struct
// ======================================================================

type StaticComposedTextPolicy struct {
	// NL→IR Item C1 Path A: the current event's typed `_event.data` payload,
	// lifted from the dequeued event by PopulateEventMetadata and read by the
	// native transition guards (`p.pending<Event>Payload.<field>`). Mirrors
	// the Rust policy's `pending_payload` / the C11 `sm->pending_payload`.
	pendingPayloadTag StaticComposedTextPayloadTag
	pendingBatchSentPayload StaticComposedTextBatchSentPayload

	pendingEventData string
	// W3C SCXML 5.10: Session ID
	SessionID string
	// ── SCE Accepted Subset §2.15: the datamodel="sce-static" variables ──
	// W3C SCXML 5.2: the `note_is_ab` datamodel variable, published (`sce:direction="out"`).
	vNoteIsAb bool
	// W3C SCXML 5.2: the `note_len` datamodel variable, published (`sce:direction="out"`).
	vNoteLen uint32
	// W3C SCXML 5.2: the `first_label_is_ab` datamodel variable, published (`sce:direction="out"`).
	vFirstLabelIsAb bool
	// W3C SCXML 5.2: the `labels_ab` datamodel variable, published (`sce:direction="out"`).
	vLabelsAb uint32
	// W3C SCXML 5.2: the `first_tags_ab` datamodel variable, published (`sce:direction="out"`).
	vFirstTagsAb uint32
	// W3C SCXML 5.2: the `words_ab` datamodel variable, published (`sce:direction="out"`).
	vWordsAb uint32
	// W3C SCXML 5.2: the `last_label` datamodel variable, published (`sce:direction="out"`).
	vLastLabel string
	// W3C SCXML 5.2: the `blob_bytes` datamodel variable, published (`sce:direction="out"`).
	vBlobBytes uint32
	// W3C SCXML 5.2: the `blobs_ab` datamodel variable, published (`sce:direction="out"`).
	vBlobsAb uint32
	// W3C SCXML 5.2: the `refusals` datamodel variable, published (`sce:direction="out"`).
	vRefusals uint32
	// W3C SCXML 6.4: Parent communication (unbounded — see sce.ParentEventQueue)
	ParentExternalQueue *sce.ParentEventQueue
	InvokeID           string
	ChildSessionID     string
	// W3C SCXML C.1: the id of the session that invoked this one, whose
	// published location reaches it as `#_parent` does (docs/adr/0090); empty
	// for a session its host started.
	ParentSessionID    string
	// §scxml-6.4.3: invoke param VALUES staged by the parent, applied after
	// this machine's datamodel init so they override its `<data>` defaults.
	pendingParams      map[string]interface{}
}

// NewStaticComposedTextPolicy creates a new policy with default values.
func NewStaticComposedTextPolicy() StaticComposedTextPolicy {
	return StaticComposedTextPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by and
		// a peer addresses it by. A host that has one for it gives it with
		// SetSessionID before it starts the machine; a child's is its parent's
		// and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vNoteIsAb: false,
		vNoteLen: 0,
		vFirstLabelIsAb: false,
		vLabelsAb: 0,
		vFirstTagsAb: 0,
		vWordsAb: 0,
		vLastLabel: "",
		vBlobBytes: 0,
		vBlobsAb: 0,
		vRefusals: 0,
	}
}

// SetSessionID gives this session the id its host has for it, in place of the
// one it drew: an XML Nmtoken, since another session addresses this one as
// `#_scxml_<id>` and every child's id is this one's and the id the child was
// started under (docs/adr/0045). Refused for anything else. Called before the
// machine starts, since what it sends names it by the id it began with.
// Declared whether or not a saved state can hold the machine: a root's id is
// bound when the machine is created, whether or not it saves.
func (p *StaticComposedTextPolicy) SetSessionID(id string) error {
	if reason := sce.SessionIDRefusalOf(id); reason != "" {
		return sce.Refuse(reason)
	}
	p.SessionID = id
	return nil
}

